// Get current item
const item = $input.first().json;

// Build the id 
const news_id = item.id;

// Extract display name from "Name <email>" or use original if no match
let from = item.email_from || '';
const match = from.match(/^([^<]+)</);  // captures everything before '<'
if (match) {
  from = match[1].trim();
}

// Strings to strip from the content
const removePhrases = [
  'View image: ',
  'Caption: ',
  'Follow image link: '
];

// Start from original content
let content = item.email_raw_content || '';

// Remove the phrases
for (const phrase of removePhrases) {
  content = content.split(phrase).join(''); // or content = content.replaceAll(phrase, '');
}

// Force to printable ASCII only -removes any non-ASCII chars
content = content.replace(/[^\x20-\x7E]/g, '');  // printable ASCII range[web:31]



// Write back cleaned content, keep other fields
return [
  {
    json: {
      news_id,
      from,
      subject: item.email_subject,
      date: item.email_date,
      to_translate: item.to_translate,
      translate_language: item.translate_language,
      content,
    }
  }
];

const item = $input.first().json;

const model = "models/gemini-flash-lite-latest";
const modelFallback = "models/gemini-2.5-flash";

let translatePrompt = (!$input.first().json.to_translate ? "using " : "translated to ") + `${item.translate_language} language`

const prompt = `Summarize this email cntent in main topics with content with 2500 chars limit ${translatePrompt} and remove any sponsored news (presented by) silently. Content >> ${item.content}`

return [
  {
    json: {
      model,
      modelFallback,
      prompt,
    }
  }
];

// Get current item
const item = $input.first().json;

// Get summmary data to transform
let summary = `**${item.email_from}**\n**${item.email_date}**\n**${item.email_subject}**\n*Summary ${item.translated} with ${item.model_used}*\n\n${item.summary_content}`;

// 0) If LLM returned literal "\n", convert to real newlines
summary = summary.replace(/\\n/g, '\n');

// 1) Replace headings with bold markers
summary = summary
  .replace(/^####\s*(.+)$/gm, '**$1**')
  .replace(/^###\s*(.+)$/gm, '**$1**')
  .replace(/^##\s*(.+)$/gm, '**$1**')
  .replace(/^---$/gm, '');

// 2) Convert bullet points BEFORE bold/italic processing
//    Handles: `*   text`, `    *   text`, `* text`, `- text`, `    - text`
summary = summary.replace(/^(\s*)[*\-]\s{2,}/gm, '$1• ');
summary = summary.replace(/^(\s*)[*\-]\s/gm, '$1• ');

// 3) Replace " with '
summary = summary.replace(/"/g, "'");

// ALL Telegram MarkdownV2 specials (including * and -)
const ALL_SPECIAL = /([_\[\]\(\)~`>#\+\-=|{}\.!\*\\])/g;
// Same but without * (for outside bold/italic spans)
const SPECIAL_NO_STAR = /([_\[\]\(\)~`>#\+\-=|{}\.!\\])/g;

function escapeKeepBoldItalic(text) {
  // 1) Temporarily mask **bold** and *italic* spans
  const placeholders = [];

  // Match **bold** first (greedy enough to allow inner *)
  text = text.replace(/\*\*([\s\S]+?)\*\*/g, (m, inner) => {
    const key = `@@BOLD${placeholders.length}@@`;
    inner = inner.replace(ALL_SPECIAL, '\\$1');
    placeholders.push(`*${inner}*`);
    return key;
  });

  // Match *italic* (no inner *, no newlines, must start with non-space)
  text = text.replace(/\*([^\s*][^*\n]*?)\*/g, (m, inner) => {
    const key = `@@ITAL${placeholders.length}@@`;
    inner = inner.replace(ALL_SPECIAL, '\\$1');
    placeholders.push(`_${inner}_`);
    return key;
  });

  // 2) Escape all specials in remaining text
  text = text.replace(SPECIAL_NO_STAR, '\\$1');
  // Also escape any leftover * that weren't part of bold/italic
  text = text.replace(/\*/g, '\\*');

  // 3) Restore bold/italic spans
  text = text.replace(/@@(?:BOLD|ITAL)(\d+)@@/g, (_, i) => placeholders[Number(i)]);

  return text;
}

const telegramMessage = escapeKeepBoldItalic(summary);

return [{
  json: {
    news_id: item.id,
    initialMessageLength: summary.length,
    finalMessageLength: telegramMessage.length,
    telegramMessage,
  }
}];

